/** The page's own game script, run on HTML inside root; env gives it the page's helpers. */
export function run(root, env) {
  const document = { getElementById: (id) => root.querySelector('#' + id), createElement: (t) => globalThis.document.createElement(t) };
  const { APP_LANG, el, cssVar, safeGet, safeSet, SCX } = env;
  let towLangHook = null;
  (function(){
  const levels = [
    { fA:15, fB:8, sameDir:false, label_en:'Team A: 15 N ← · Team B: 8 N →', label_ta:'அணி A: 15 N ← · அணி B: 8 N →' },
    { fA:12, fB:20, sameDir:false, label_en:'Team A: 12 N ← · Team B: 20 N →', label_ta:'அணி A: 12 N ← · அணி B: 20 N →' },
    { fA:9, fB:9, sameDir:false, label_en:'Team A: 9 N ← · Team B: 9 N → (careful!)', label_ta:'அணி A: 9 N ← · அணி B: 9 N → (கவனம்!)' },
    { fA:14, fB:11, sameDir:true, label_en:'Two friends pull the SAME way: 14 N + 11 N', label_ta:'இருவரும் ஒரே திசையில் இழுக்கிறார்கள்: 14 N + 11 N' },
    { fA:23, fB:19, sameDir:false, label_en:'Boss level! Team A: 23 N ← · Team B: 19 N →', label_ta:'பாஸ் லெவல்! அணி A: 23 N ← · அணி B: 19 N →' }
  ];
  const levelRow = document.getElementById('towLevelRow');
  const levelDesc = document.getElementById('towLevelDesc');
  const towSvg = document.getElementById('towSvg');
  const guessSlider = document.getElementById('towGuessSlider');
  const guessVal = document.getElementById('towGuessVal');
  const pullBtn = document.getElementById('towPullBtn');
  const resultEl = document.getElementById('towResult');
  const starsEl = document.getElementById('towStars');

  let curLevel = 0;
  let bestStars = JSON.parse(safeGet('scx_tow_stars') || '[0,0,0,0,0]');

  function correctResultant(lv){ return lv.sameDir ? (lv.fA + lv.fB) : Math.abs(lv.fA - lv.fB); }

  function drawScene(pulled, dir){
    towSvg.innerHTML = '';
    const x0=40,x1=520,y=45;
    towSvg.appendChild(el('line',{x1:x0,y1:y,x2:x1,y2:y,stroke:cssVar('--border'),'stroke-width':3}));
    let cx = 280;
    if(pulled){ cx += (dir>0 ? 120 : (dir<0 ? -120 : 0)); }
    towSvg.appendChild(el('circle',{cx:cx,cy:y,r:10,fill:cssVar('--accent'),stroke:cssVar('--bg'),'stroke-width':2}));
  }

  function renderLevelRow(){
    levelRow.innerHTML = '';
    levels.forEach((lv,i)=>{
      const b = document.createElement('div');
      b.className = 'level-btn' + (i===curLevel ? ' active' : '');
      const stars = bestStars[i] || 0;
      b.innerHTML = '<div class="lnum2">'+(i+1)+'</div><div class="lstars">'+('★'.repeat(stars)+'☆'.repeat(3-stars))+'</div>';
      b.addEventListener('click', ()=>{ curLevel = i; loadLevel(); });
      levelRow.appendChild(b);
    });
  }
  function loadLevel(){
    renderLevelRow();
    const lv = levels[curLevel];
    levelDesc.textContent = (APP_LANG==='ta') ? lv.label_ta : lv.label_en;
    resultEl.textContent = ''; resultEl.className = 'game-result';
    starsEl.textContent = '';
    drawScene(false, 0);
  }
  guessSlider.addEventListener('input', ()=>{ guessVal.textContent = guessSlider.value; });

  pullBtn.addEventListener('click', ()=>{
    const lv = levels[curLevel];
    const correct = correctResultant(lv);
    const guess = parseFloat(guessSlider.value);
    const err = Math.abs(guess - correct);
    const winDir = lv.sameDir ? 1 : (lv.fB > lv.fA ? 1 : (lv.fA > lv.fB ? -1 : 0));
    drawScene(true, winDir);
    let stars;
    if(err <= 1) stars = 3;
    else if(err <= 3) stars = 2;
    else if(err <= 6) stars = 1;
    else stars = 0;

    if(stars === 0){
      resultEl.textContent = (APP_LANG==='ta') ? '😅 நல்ல முயற்சி, ஆனா தூரமா இருக்கு. சரியான விளையுள் = '+correct.toFixed(0)+' N.' : "😅 Nice try, but that's off. The correct resultant was "+correct.toFixed(0)+' N.';
      resultEl.className = 'game-result lose';
      SCX.sndWrong();
    } else {
      resultEl.textContent = (APP_LANG==='ta') ? '🎉 சரியான விளையுள் = '+correct.toFixed(0)+' N!' : '🎉 The correct resultant was '+correct.toFixed(0)+' N!';
      resultEl.className = 'game-result win';
    }
    starsEl.textContent = stars>0 ? ('★'.repeat(stars) + '☆'.repeat(3-stars)) : '';

    const prevBest = bestStars[curLevel] || 0;
    if(stars > prevBest){
      bestStars[curLevel] = stars;
      safeSet('scx_tow_stars', JSON.stringify(bestStars));
      if(stars>0) SCX.pushItLevelResult(stars, bestStars.every(s=>s>0));
    } else if(stars>0){
      SCX.sndCorrect();
    }
    renderLevelRow();
  });

  loadLevel();
  towLangHook = function(){ levelDesc.textContent = (APP_LANG==='ta') ? levels[curLevel].label_ta : levels[curLevel].label_en; renderLevelRow(); };
})();
  return { lang: () => towLangHook && towLangHook() };
}
